import { kartsLivres, podeSortear, sortear, type PilotoPainel } from '../src/features/operacao/sorteio';
const p = (nome: string, excecoes: string[] = [], situacao = 'ELEGIVEL') => ({ indice: 0, nome, customerId: nome, kartAtual: '', excecoes, pesoKg: null, situacao, motivo: null, lastro: null, lastroConferido: false }) as PilotoPainel;

describe('sorteio no app', () => {
  it('não repete kart e dá um para cada', () => {
    const r = sortear([p('a'), p('b'), p('c')], ['1', '2', '3']);
    expect(new Set(r.atribuicoes.map((x) => x.kart)).size).toBe(3);
    expect(r.semKart).toEqual([]);
  });
  it('evita kart já usado pelo piloto', () => {
    for (let i = 0; i < 30; i++) expect(sortear([p('a', ['1']), p('b')], ['1', '2']).atribuicoes.find((x) => x.nome === 'a')!.kart).toBe('2');
  });
  it('avisa quem ficou sem kart', () => {
    expect(sortear([p('a'), p('b')], ['1']).semKart).toHaveLength(1);
  });
  it('só aptos e karts livres da frota', () => {
    expect(podeSortear(p('x', [], 'INELEGIVEL'))).toBe(false);
    expect(podeSortear(p('x', [], 'INDETERMINADA'))).toBe(false);
    expect(kartsLivres([{ kart: '1', frota: 'LIGHT', fora: false, ocupado: false }, { kart: '2', frota: 'LIGHT', fora: true, ocupado: false }, { kart: '3', frota: 'LIGHT', fora: false, ocupado: true }, { kart: '100', frota: 'SUPER', fora: false, ocupado: false }], 'LIGHT')).toEqual(['1']);
  });
});

describe('formatos', () => {
  const { relogio, volta } = require('../src/features/operacao/formato');
  it('relógio', () => { expect(relogio(521000)).toBe('08:41'); expect(relogio(null)).toBe('--:--'); expect(relogio(-5)).toBe('00:00'); });
  it('volta', () => { expect(volta(58412)).toBe('58,412'); expect(volta(62410)).toBe('1:02,410'); expect(volta(null)).toBe('—'); });
});
